package com.quincaisoft.integrations.application;
import com.quincaisoft.integrations.api.*;import com.quincaisoft.integrations.infrastructure.ProviderIntentEntity;import com.quincaisoft.shared.*;import com.quincaisoft.finance.api.FinanceService;import com.quincaisoft.sales.api.SalesService;
import jakarta.persistence.*;import org.springframework.stereotype.Service;import tools.jackson.databind.json.JsonMapper;import java.util.*;import java.security.*;import java.nio.charset.StandardCharsets;
@Service public class DefaultMobileMoneyService implements MobileMoneyService {
 private final EntityManager em;private final ScopedTransactions tx;private final FinanceService finance;private final SalesService sales;private final ProviderRuntime runtime;private final JsonMapper json;
 public DefaultMobileMoneyService(EntityManager em,ScopedTransactions tx,FinanceService finance,SalesService sales,ProviderRuntime runtime,JsonMapper json){this.em=em;this.tx=tx;this.finance=finance;this.sales=sales;this.runtime=runtime;this.json=json;}
 private void enabled(){if(!runtime.configured())throw new IllegalStateException("Provider merchant configuration is incomplete");}
 private ProviderIntentEntity get(UUID id){var s=TenantContext.current();var r=em.find(ProviderIntentEntity.class,new ProviderIntentEntity.Key(s.tenantId(),s.companyId(),id),LockModeType.PESSIMISTIC_WRITE);if(r==null||!r.branchId.equals(s.branchId()))throw new NoSuchElementException("Provider intent not found");return r;}
 private Intent view(ProviderIntentEntity r){return new Intent(r.id,r.saleId,""+r.amountXaf,r.currency,r.environment,r.status,r.id.toString(),r.journalId,r.version);}
 public List<Intent> list(){return tx.execute(()->em.createQuery("select r from ProviderIntentEntity r order by r.businessDate desc,r.id",ProviderIntentEntity.class).setMaxResults(200).getResultList().stream().map(this::view).toList());}
 public Intent prepare(Prepare p){enabled();if(p.operationId()==null||p.saleId()==null||p.businessDate()==null||p.amountXaf()==null||!p.amountXaf().matches("[1-9][0-9]*")||p.phone()==null||!p.phone().matches("[0-9]{9,15}")||p.reason()==null||p.reason().trim().length()<3||p.reason().length()>2000)throw new IllegalArgumentException("Valid intent, date, phone, exact positive XAF amount and reason required");if(!runtime.environment().equals("sandbox")&&!p.phone().matches("2376[0-9]{8}"))throw new IllegalArgumentException("Cameroon mobile number required");long amount=Long.parseLong(p.amountXaf());return tx.execute(()->{var s=TenantContext.current();var sale=sales.get(p.saleId());if(!sale.status().equals("POSTED"))throw new IllegalArgumentException("Posted sale required");String hash=hash(p.toString()+runtime.environment());em.createNativeQuery("select 1 from pg_advisory_xact_lock(hashtextextended(:k,0))").setParameter("k",s.tenantId()+":"+p.operationId()).getSingleResult();var existing=em.createNativeQuery("select request_hash,company_id,branch_id,response_json::text,source_id from idempotency_result where tenant_id=:t and operation_id=:o").setParameter("t",s.tenantId()).setParameter("o",p.operationId()).getResultList();if(!existing.isEmpty()){Object[] row=(Object[])existing.getFirst();if(!hash.equals(row[0])||!s.companyId().equals(row[1])||!s.branchId().equals(row[2]))throw new IllegalStateException("Operation conflicts with prior request");get((UUID)row[4]);if(row[3]==null)throw new IllegalStateException("Provider intent already committed; query existing intent");return json.readValue((String)row[3],Intent.class);}
  finance.requireOpenPeriod(p.businessDate());long debt=finance.outstandingSale(p.saleId());if(amount>debt)throw new IllegalArgumentException("Collection exceeds current debt");if(!runtime.environment().equals("sandbox")){long reserved=0;for(var prior:em.createQuery("select r from ProviderIntentEntity r where r.saleId=:s and r.environment<>'sandbox' and r.status not in ('FAILED','CONFIRMED')",ProviderIntentEntity.class).setParameter("s",p.saleId()).getResultList())reserved=Math.addExact(reserved,prior.amountXaf);if(Math.addExact(reserved,amount)>debt)throw new IllegalArgumentException("Collection exceeds debt after pending intents");}
  var r=new ProviderIntentEntity();r.tenantId=s.tenantId();r.companyId=s.companyId();r.branchId=s.branchId();r.id=UUID.randomUUID();r.operationId=p.operationId();r.saleId=p.saleId();r.actorId=s.actorId();r.businessDate=p.businessDate();r.amountXaf=amount;r.currency=runtime.environment().equals("sandbox")?"EUR":"XAF";r.environment=runtime.environment();r.phone=p.phone();r.reason=p.reason();r.status="QUEUED";r.queryDue=true;em.persist(r);em.flush();var result=view(r);
  em.createNativeQuery("insert into idempotency_result(tenant_id,operation_id,company_id,branch_id,request_hash,source_type,source_id,response_json) values(:t,:o,:c,:b,:h,'PROVIDER_INTENT',:i,cast(:r as jsonb))").setParameter("t",s.tenantId()).setParameter("o",p.operationId()).setParameter("c",s.companyId()).setParameter("b",s.branchId()).setParameter("h",hash).setParameter("i",r.id).setParameter("r",json.writeValueAsString(result)).executeUpdate();em.createNativeQuery("insert into outbox_event(tenant_id,id,company_id,branch_id,operation_id,event_type,aggregate_type,aggregate_id,payload) values(:t,:i,:c,:b,:o,'ProviderCollectionRequested.v1','provider_intent',:a,cast(:p as jsonb))").setParameter("t",s.tenantId()).setParameter("i",UUID.randomUUID()).setParameter("c",s.companyId()).setParameter("b",s.branchId()).setParameter("o",p.operationId()).setParameter("a",r.id).setParameter("p","{\"intentId\":\""+r.id+"\"}").executeUpdate();return result;});}
 private record Dispatch(CollectionProvider.Intent intent,boolean initiate,boolean terminal){}
 public Intent reconcile(UUID id){enabled();if(em.isJoinedToTransaction())throw new IllegalStateException("Provider reconciliation must start outside a business transaction");var dispatch=tx.execute(()->{var r=get(id);if(!r.environment.equals(runtime.environment()))throw new IllegalStateException("Intent environment differs from merchant configuration");boolean terminal=Set.of("CONFIRMED","FAILED","SANDBOX_VERIFIED","PROVIDER_VERIFIED_REVIEW").contains(r.status);boolean initial=r.status.equals("QUEUED");if(initial){r.status="UNKNOWN";em.flush();}return new Dispatch(new CollectionProvider.Intent(r.id,r.saleId.toString(),r.phone,""+r.amountXaf,r.currency),initial,terminal);});
  if(!dispatch.terminal()){CollectionProvider.Result response;try{response=dispatch.initiate()?runtime.provider().initiate(dispatch.intent()):runtime.provider().query(dispatch.intent());}catch(RuntimeException unavailable){response=new CollectionProvider.Result(CollectionProvider.Outcome.UNKNOWN,null);}var result=response;tx.execute(()->{var r=get(id);if(Set.of("CONFIRMED","FAILED","SANDBOX_VERIFIED","PROVIDER_VERIFIED_REVIEW").contains(r.status))return null;switch(result.outcome()){case VERIFIED->{if(r.environment.equals("sandbox")||result.financialTransactionId()==null||result.financialTransactionId().isBlank())throw new IllegalStateException("Invalid verified provider result");r.status="PROVIDER_VERIFIED_REVIEW";r.financialTransactionId=result.financialTransactionId();}case SANDBOX_VERIFIED->{if(!r.environment.equals("sandbox"))throw new IllegalStateException("Sandbox outcome cannot settle live collection");r.status="SANDBOX_VERIFIED";}case FAILED->r.status="FAILED";case PENDING->r.status="PENDING";case UNKNOWN->r.status="UNKNOWN";}r.queryDue=Set.of("PENDING","UNKNOWN").contains(r.status);em.flush();return null;});}
  try{tx.execute(()->{var r=get(id);if(!r.status.equals("PROVIDER_VERIFIED_REVIEW"))return null;finance.applyReceipt(r.saleId,r.amountXaf);UUID op=UUID.nameUUIDFromBytes(("provider-accounting:"+r.id).getBytes(StandardCharsets.UTF_8));r.journalId=finance.post(r.id,op,r.businessDate,"MTN_COLLECTION",List.of(new FinanceService.Entry("PROVIDER_CLEARING",r.amountXaf,0),new FinanceService.Entry("ACCOUNTS_RECEIVABLE",0,r.amountXaf)));r.status="CONFIRMED";r.queryDue=false;em.flush();em.createNativeQuery("insert into outbox_event(tenant_id,id,company_id,branch_id,operation_id,event_type,aggregate_type,aggregate_id,payload) values(:t,:i,:c,:b,:o,'ProviderCollectionConfirmed.v1','provider_intent',:a,cast(:p as jsonb))").setParameter("t",r.tenantId).setParameter("i",UUID.randomUUID()).setParameter("c",r.companyId).setParameter("b",r.branchId).setParameter("o",op).setParameter("a",r.id).setParameter("p","{\"intentId\":\""+r.id+"\"}").executeUpdate();return null;});}catch(RuntimeException accountingUnavailable){/* Verified provider evidence was committed first. Review remains retriable without a second charge. */}
  return tx.execute(()->view(get(id)));
 }
 public void callbackHint(UUID id){tx.execute(()->{get(id).queryDue=true;return null;});}
 static String hash(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
}
